<script setup lang="ts">import { AlertCircle, FilterX, Inbox, Plus, RefreshCw } from "lucide-vue-next"; defineProps<{kind:"loading"|"error"|"empty"|"no-results";message?:string|null;canCreate:boolean}>(); const emit=defineEmits<{retry:[];clear:[];create:[]}>();</script>
<template><div v-if="kind==='loading'" class="space-y-2" role="status" aria-label="Cargando sistemas"><div v-for="index in 6" :key="index" class="h-14 animate-pulse rounded-lg border border-gray-100 bg-gray-100 motion-reduce:animate-none"/></div><div v-else class="grid min-h-56 place-items-center rounded-lg border border-dashed border-gray-300 bg-gray-50/60 p-6 text-center"><div><AlertCircle v-if="kind==='error'" class="mx-auto h-7 w-7 text-danger"/><FilterX v-else-if="kind==='no-results'" class="mx-auto h-7 w-7 text-main"/><Inbox v-else class="mx-auto h-7 w-7 text-main"/><h3 class="mt-2 text-sm font-bold">{{ kind==='error'?'No se pudieron cargar los sistemas':kind==='no-results'?'Sin coincidencias':'Catálogo vacío' }}</h3><p class="mt-1 text-xs text-gray-500">{{ kind==='error'?message:kind==='no-results'?'No encontramos sistemas con los filtros actuales.':'No hay sistemas registrados.' }}</p><button v-if="kind==='error'" type="button" class="mt-4 inline-flex min-h-11 cursor-pointer items-center gap-2 rounded-md border bg-white px-3 text-xs font-semibold text-main" @click="emit('retry')"><RefreshCw class="h-4 w-4"/>Reintentar</button><button v-else-if="kind==='no-results'" type="button" class="mt-4 inline-flex min-h-11 cursor-pointer items-center gap-2 rounded-md border bg-white px-3 text-xs font-semibold text-main" @click="emit('clear')"><FilterX class="h-4 w-4"/>Limpiar filtros</button><button v-else-if="canCreate" type="button" class="mt-4 inline-flex min-h-11 cursor-pointer items-center gap-2 rounded-md bg-main px-3 text-xs font-semibold text-white" @click="emit('create')"><Plus class="h-4 w-4"/>Nuevo sistema</button></div></div></template>
